#!/usr/bin/env python3
from pathlib import Path
import json
import re
import subprocess

ROOT = Path(__file__).resolve().parents[1]

PT_LIMONADA = '''<div class="phase" data-bio-key="music-limonada-1992" id="destemidos-limonadas-punkecas-1992"><div class="phase-year">1992</div><div><h3>Destemidos Limonadas &amp; Punkecas / Roberto Limonada</h3><p>Em 1992, quando o <strong>Coitado do Próximo</strong> ainda estava no começo, um encontro casual ampliou o horizonte musical de Nicchio. Num dia em que havia cabulado aula e passava o tempo lendo jornal na banca de <strong>Márcio</strong>, amigo e dono da banca, Márcio chamou sua atenção para um homem que passava: <strong>Roberto Sassano</strong>, conhecido na cena como <strong>Roberto Limonada</strong> — ou simplesmente Limonada.</p><p>Nicchio tinha entre 15 e 16 anos e atravessava um período de desorientação pessoal depois da separação dos pais. Já tocava e começava a compor, mas ainda procurava uma identidade musical própria. A aproximação com Roberto passou a representar algo maior do que conhecer um músico mais experiente: abriu uma possibilidade concreta de pertencimento, repertório e vida ligada ao punk rock.</p><p>Roberto era proprietário de um <strong>posto Esso na Avenida Brás Leme</strong>, a mesma avenida onde Nicchio morava, e tocava com os <strong>Destemidos Limonadas &amp; Punkecas</strong>. A banda estava prestes a se apresentar no <strong>Café Piu Piu</strong>, no Bexiga, e aparecia com foto em uma matéria do extinto <em>Diário de São Paulo</em>. Márcio abriu o jornal e apontou para a imagem: <q>Olha quem é esse cara, olha eles aqui.</q></p><p>O próprio posto também virou matéria-prima para o humor da banda em <strong>“O Posto”</strong>, um rock de duplo sentido registrado em apresentação na TV Cultura de São Paulo.</p><div class="evidence-links inline-links"><a href="https://www.youtube.com/watch?v=_LBHqq8xF1c" target="_blank" rel="noopener noreferrer">Assistir “O Posto” · TV Cultura ↗</a></div><p>Da conversa nasceu uma amizade alimentada principalmente por <strong>Ramones</strong> e punk rock. Nicchio ainda vinha de uma escuta muito marcada pelo thrash metal — com <strong>Ratos de Porão</strong> entre as referências mais presentes — enquanto Roberto possuía um conhecimento profundo da história e da cena punk. Ramones, paixão que Nicchio já carregava, para Limonada era quase uma religião. Nicchio passou a frequentar o escritório do posto para ouvir rádio e conversar sobre bandas, discos, shows e a cena paulistana.</p><p>Em <strong>junho de 1992</strong>, Roberto telefonou para avisar que os Destemidos seriam entrevistados naquela noite no <strong>Jô Soares Onze e Meia</strong>, no SBT. Para um adolescente que ainda tentava encontrar seu lugar, ver na televisão nacional uma banda punk ligada a alguém que havia acabado de entrar em sua vida teve um efeito decisivo: um universo antes distante ganhou proximidade e possibilidade.</p><p>Os Destemidos já mantinham também uma ligação com <strong>Kid Vinil</strong>. O baixista da banda era amigo de longa data de Kid, que enxergou em <strong>“Ela Só Gosta de Pizza”</strong> uma música com força para integrar sua retomada artística. A canção passou ao repertório de Kid Vinil e Verminose e se tornaria o elo mais visível entre as duas bandas. Essa história ganharia um capítulo próprio em 1993, quando Roberto levaria Nicchio a um show de Kid no Café Piu Piu.</p><p>A convivência de Nicchio com os Destemidos continuou em ensaios e shows, inclusive no circuito do Aeroanta. A influência também atravessou diretamente o repertório do <strong>Coitado do Próximo</strong>: a partir de <strong>1993</strong>, a banda passou a tocar <strong>“Ela Só Gosta de Pizza”</strong> em ensaios e apresentações. Em <strong>9 de março de 1995</strong>, Limonada esteve entre as grandes surpresas da festa de 18 anos de Nicchio; em 1998, o Coitado incorporou uma versão de <strong>“Ali Babão”</strong>, dos Destemidos, que segundo a lembrança de Nicchio ficou entre as músicas mais aplaudidas daquela noite e recebeu elogios de <strong>Paulão de Carvalho</strong>; e, por volta de <strong>2000/2001</strong>, Roberto foi convidado a participar de um show do Coitado no <strong>Rock n Roll Bar</strong>, ligado a Paulão e às Velhas Virgens. A música específica dessa participação ainda não está identificada no arquivo.</p></div></div>'''

PT_KID = '''<div class="phase" data-bio-key="music-kid-vinil-1993" id="kid-vinil-verminose-cafe-piu-piu-1993"><div class="phase-year">1993</div><div><h3>Kid Vinil &amp; Verminose — Café Piu Piu</h3><p>A ligação entre os <strong>Destemidos Limonadas &amp; Punkecas</strong> e <strong>Kid Vinil</strong> já existia quando Nicchio conheceu Roberto Limonada. O baixista dos Destemidos era amigo de longa data de Kid e, ao conhecer o repertório da banda, Kid enxergou em <strong>“Ela Só Gosta de Pizza”</strong> uma música capaz de marcar uma nova fase. Ele incorporou a composição ao repertório de <strong>Kid Vinil e Verminose</strong>, enquanto também fazia nos shows uma versão de <strong>“O Posto”</strong>.</p><p>Foi dentro desse contexto que, em 1993, <strong>Roberto Limonada levou Nicchio ao Café Piu Piu</strong>, no Bexiga, para assistir a Kid Vinil e Verminose. Nicchio já havia ido a uma grande apresentação de pop — Roxette, acompanhado da então namorada —, mas aquela noite ficou em sua memória como o primeiro show de rock que sentiu verdadeiramente como parte do mundo que estava descobrindo.</p><p>A experiência atravessou a madrugada, aproximadamente das <strong>22h às 5h</strong>, com três entradas de bandas. Roberto levou Nicchio também ao camarim, onde pôde observar Kid de perto em uma estética punk que permaneceria gravada em sua memória: roupa punk, coturno verde-musgo de aparência quase vinílica, cadarços vermelhos e uma composição visual que Nicchio recorda como tendo algo de soviético. No palco, Kid misturava repertório próprio e referências como <strong>Ramones</strong>, incluindo <strong>“Suzy Is a Headbanger”</strong>.</p><p>Naquela fase, <strong>“Ela Só Gosta de Pizza”</strong> já fazia parte do repertório de Kid. Meses depois daquele show, em <strong>1993</strong>, Kid Vinil e Verminose apareceram no <strong>Programa Livre</strong>, de Serginho Groisman, no SBT, apresentando uma versão mais punk rock da música como uma das grandes novidades de sua reaparição na mídia. Kid também faria participações em shows dos Destemidos, reforçando publicamente a ligação entre os dois projetos.</p><p>Antes do lançamento de um novo álbum, <strong>“Ela Só Gosta de Pizza”</strong> já havia circulado como single e tocado nas rádios rock de São Paulo. Em <strong>1995</strong>, Kid Vinil lançou <strong><em>Xu-Pa-Ki</em></strong>, com a música entre as dez faixas do disco, consolidando em álbum um percurso que havia começado anos antes no circuito paulistano.</p><p>Para Nicchio, aquela madrugada no Café Piu Piu funcionou como um rito de passagem. O que Roberto vinha apresentando em conversas, discos, rádio e televisão se tornou experiência física: palco, camarim, público, estética e repertório. Em pouco tempo, esse mesmo circuito deixaria de ser apenas algo observado de fora e passaria a receber também o próprio Coitado do Próximo.</p></div></div>'''

PT_97 = '''<div data-bio-key="music-coitado-1994"><p>Em <strong>abril e maio de 1994</strong>, o Coitado do Próximo gravou no <strong>Estúdio Anonimato</strong> sua primeira demo-tape: <strong>“Mulher SP”</strong> no lado A e <strong>“Pegue o Seu Celular”</strong> no lado B. No mesmo ano, <strong>Roberto Limonada</strong> levou Nicchio à <strong>97FM Rock</strong> e o apresentou a <strong>Kid Vinil</strong>. A banda foi recebida no programa de Kid e levou a demo recém-gravada; foi nessa passagem que <strong>“Mulher SP”</strong> foi apresentada no rádio pela primeira vez.</p><p>Houve ainda uma segunda passagem pelo programa, em circunstâncias bem diferentes. Na fase em que o Coitado já havia aberto vários shows do <strong>365</strong> e mantinha amizade com <strong>Finho</strong>, <strong>Ari</strong>, <strong>Junião</strong> e <strong>Mirão</strong>, integrantes das duas bandas estavam em um bar com Mirão, dias antes de mais uma apresentação, conversando sobre divulgação. Ao lembrarem que Kid Vinil estava no ar naquele momento, surgiu a ideia de aparecer na rádio sem convite para divulgar o show. Mirão, figura já conhecida da cena punk paulistana, topou funcionar como uma espécie de fiador informal da aventura.</p><p>O grupo já conhecia o endereço e, numa época em que o acesso à emissora era muito menos fechado, simplesmente apareceu. Kid mandou todos entrarem. O Coitado chegou com violão e gaita, Mirão divulgou o show e a visita terminou com uma versão acústica de <strong>“Pegue o Seu Celular”</strong>, em voz, violão e gaita, executada ao vivo no programa. A data exata dessa segunda passagem ainda não está identificada no arquivo.</p><p>Assim, o Coitado do Próximo passou duas vezes pelo programa de Kid Vinil na 97FM Rock: uma como convidado, levando <strong>“Mulher SP”</strong> da primeira demo; outra no melhor espírito punk, chegando sem convite para divulgar um show e tocando <strong>“Pegue o Seu Celular”</strong> ao vivo.</p></div>'''

EN_LIMONADA = '''<div class="phase" data-bio-key="music-limonada-1992" id="destemidos-limonadas-punkecas-1992"><div class="phase-year">1992</div><div><h3>Destemidos Limonadas &amp; Punkecas / Roberto Limonada</h3><p>In 1992, while <strong>Coitado do Próximo</strong> was still taking shape, a chance encounter widened Nicchio's musical horizon. One day, after skipping class and spending time reading newspapers at the newsstand run by his friend <strong>Márcio</strong>, Márcio called his attention to a man passing by: <strong>Roberto Sassano</strong>, known in the scene as <strong>Roberto Limonada</strong> — or simply Limonada.</p><p>Nicchio was between 15 and 16 years old and going through a period of personal disorientation after his parents' separation. He was already playing music and beginning to write songs, but he had not yet found a musical identity of his own. Becoming close to Roberto came to mean more than simply meeting a more experienced musician: it opened up a concrete possibility of belonging, repertoire and a life connected to punk rock.</p><p>Roberto owned an <strong>Esso gas station on Avenida Brás Leme</strong>, the same avenue where Nicchio lived, and played with <strong>Destemidos Limonadas &amp; Punkecas</strong>. The band was about to perform at <strong>Café Piu Piu</strong> in Bexiga and had appeared with a photograph in the now-defunct <em>Diário de São Paulo</em>. Márcio opened the paper and pointed at the picture: <q>Look who this guy is — look, they're right here.</q></p><p>The gas station itself also became material for the band's humor in <strong>“O Posto”</strong>, a double-entendre rock song preserved in a performance recorded by TV Cultura in São Paulo.</p><div class="evidence-links inline-links"><a href="https://www.youtube.com/watch?v=_LBHqq8xF1c" target="_blank" rel="noopener noreferrer">Watch “O Posto” · TV Cultura ↗</a></div><p>A friendship grew out of that conversation, held together above all by <strong>Ramones</strong> and punk rock. Nicchio still came from listening habits strongly shaped by thrash metal — with <strong>Ratos de Porão</strong> among his closest references — while Roberto had a deep knowledge of punk history and the local scene. Ramones, already a passion for Nicchio, were almost a religion to Limonada. Nicchio began spending time in the gas station office listening to the radio and talking about bands, records, shows and the São Paulo scene.</p><p>In <strong>June 1992</strong>, Roberto called to say that the Destemidos would be interviewed that night on <strong>Jô Soares Onze e Meia</strong> on SBT. For a teenager still trying to find his place, seeing on national television a punk band connected to someone who had just entered his life had a decisive effect: a world that had seemed distant suddenly felt close and possible.</p><p>The Destemidos already had a connection with <strong>Kid Vinil</strong>. The band's bassist was a longtime friend of Kid, who saw in <strong>“Ela Só Gosta de Pizza”</strong> a song strong enough to become part of his artistic comeback. The song entered the repertoire of Kid Vinil e Verminose and would become the most visible link between the two bands. That story would gain a chapter of its own in 1993, when Roberto took Nicchio to a Kid Vinil show at Café Piu Piu.</p><p>Nicchio's contact with the Destemidos continued through rehearsals and shows, including the Aeroanta circuit. Their influence also crossed directly into the repertoire of <strong>Coitado do Próximo</strong>: starting in <strong>1993</strong>, the band began playing <strong>“Ela Só Gosta de Pizza”</strong> in rehearsals and live performances. On <strong>March 9, 1995</strong>, Limonada was among the biggest surprises at Nicchio's 18th-birthday party; in 1998, Coitado added a version of <strong>“Ali Babão”</strong>, by the Destemidos, which Nicchio remembers as one of the most applauded songs of that night and as drawing praise from <strong>Paulão de Carvalho</strong>; and around <strong>2000/2001</strong>, Roberto was invited to join Coitado onstage at the <strong>Rock n Roll Bar</strong>, associated with Paulão and Velhas Virgens. The specific song from that guest appearance has not yet been identified in the archive.</p></div></div>'''

EN_KID = '''<div class="phase" data-bio-key="music-kid-vinil-1993" id="kid-vinil-verminose-cafe-piu-piu-1993"><div class="phase-year">1993</div><div><h3>Kid Vinil &amp; Verminose — Café Piu Piu</h3><p>The connection between <strong>Destemidos Limonadas &amp; Punkecas</strong> and <strong>Kid Vinil</strong> already existed when Nicchio met Roberto Limonada. The Destemidos' bassist was a longtime friend of Kid and, after hearing the band's repertoire, Kid saw in <strong>“Ela Só Gosta de Pizza”</strong> a song that could mark a new phase. He added the composition to the repertoire of <strong>Kid Vinil e Verminose</strong>, while also performing a version of <strong>“O Posto”</strong> at shows.</p><p>It was in this context that, in 1993, <strong>Roberto Limonada took Nicchio to Café Piu Piu</strong>, in Bexiga, to see Kid Vinil e Verminose. Nicchio had already attended a major pop concert — Roxette, with his then-girlfriend — but he remembers that night as the first rock show that truly felt like part of the world he was discovering.</p><p>The experience stretched through the night, roughly from <strong>10 p.m. to 5 a.m.</strong>, with three separate band sets. Roberto also took Nicchio backstage, where he saw Kid up close in a punk aesthetic that remained fixed in his memory: punk clothing, moss-green boots with an almost vinyl-like appearance, red laces and a visual composition Nicchio remembers as having something almost Soviet about it. Onstage, Kid mixed his own repertoire with references such as the <strong>Ramones</strong>, including <strong>“Suzy Is a Headbanger”</strong>.</p><p>By then, <strong>“Ela Só Gosta de Pizza”</strong> was already part of Kid's repertoire. Months after that show, in <strong>1993</strong>, Kid Vinil e Verminose appeared on <strong>Programa Livre</strong>, hosted by Serginho Groisman on SBT, presenting a more punk-rock version of the song as one of the main novelties of Kid's return to the media. Kid would also make guest appearances at Destemidos shows, publicly reinforcing the connection between the two projects.</p><p>Before the release of a new album, <strong>“Ela Só Gosta de Pizza”</strong> had already circulated as a single and received airplay on São Paulo rock radio stations. In <strong>1995</strong>, Kid Vinil released <strong><em>Xu-Pa-Ki</em></strong>, with the song among the album's ten tracks, consolidating on record a path that had begun years earlier in the São Paulo club circuit.</p><p>For Nicchio, that night at Café Piu Piu worked as a rite of passage. What Roberto had been introducing through conversations, records, radio and television became a physical experience: stage, backstage, audience, aesthetics and repertoire. Before long, that same circuit would stop being something observed from the outside and would begin to receive Coitado do Próximo itself.</p></div></div>'''

EN_97 = '''<div data-bio-key="music-coitado-1994"><p>In <strong>April and May 1994</strong>, Coitado do Próximo recorded its first demo tape at <strong>Estúdio Anonimato</strong>: <strong>“Mulher SP”</strong> on side A and <strong>“Pegue o Seu Celular”</strong> on side B. That same year, <strong>Roberto Limonada</strong> took Nicchio to <strong>97FM Rock</strong> and introduced him to <strong>Kid Vinil</strong>. The band was welcomed onto Kid's program and brought the newly recorded demo; it was during this appearance that <strong>“Mulher SP”</strong> was played on the radio for the first time.</p><p>There was also a second appearance on the program, under very different circumstances. By then Coitado had opened several shows for <strong>365</strong> and had become friends with <strong>Finho</strong>, <strong>Ari</strong>, <strong>Junião</strong> and <strong>Mirão</strong>. Members of the two bands were at a bar with Mirão a few days before another show, talking about promotion. When they remembered that Kid Vinil was on the air at that very moment, someone suggested simply showing up at the station without an invitation to promote the show. Mirão, already a recognizable figure in São Paulo's punk scene, agreed to act as an informal guarantor for the adventure.</p><p>The group already knew the address and, at a time when access to the station was far less restricted, simply showed up. Kid told everyone to come in. Coitado arrived with an acoustic guitar and harmonica, Mirão promoted the show, and the visit ended with an acoustic version of <strong>“Pegue o Seu Celular”</strong>, performed live with voice, guitar and harmonica. The exact date of this second appearance has not yet been identified in the archive.</p><p>Coitado do Próximo therefore appeared twice on Kid Vinil's program on 97FM Rock: once as invited guests, bringing <strong>“Mulher SP”</strong> from the first demo; and once in the best punk spirit, arriving without an invitation to promote a show and performing <strong>“Pegue o Seu Celular”</strong> live.</p></div>'''


def replace_section(path: Path, lang: str):
    text = path.read_text(encoding='utf-8')
    limonada = PT_LIMONADA if lang == 'pt' else EN_LIMONADA
    kid = PT_KID if lang == 'pt' else EN_KID
    radio = PT_97 if lang == 'pt' else EN_97

    # Replace Limonada phase and insert Kid phase immediately after it.
    pat = re.compile(r'<div class="phase" data-bio-key="music-limonada-1992" id="destemidos-limonadas-punkecas-1992">.*?</div></div>\n(?=<div class="phase" id="estudios-shows-1993">)', re.S)
    text, n = pat.subn(limonada + '\n' + kid + '\n', text, count=1)
    if n != 1:
        raise RuntimeError(f'{path}: Limonada phase replacement failed ({n})')

    # Replace the existing 97FM entry but leave surrounding section structure unchanged.
    pat97 = re.compile(r'<div data-bio-key="music-coitado-1994">.*?</div>(?=</section>\n<section id="(?:palcos|stages)")', re.S)
    text, n = pat97.subn(radio, text, count=1)
    if n != 1:
        raise RuntimeError(f'{path}: 97FM replacement failed ({n})')

    path.write_text(text, encoding='utf-8')


replace_section(ROOT / 'pt/musica/index.html', 'pt')
replace_section(ROOT / 'en/music/index.html', 'en')

manifest_path = ROOT / 'data/full_biography.json'
manifest = json.loads(manifest_path.read_text(encoding='utf-8'))
entries = manifest.get('entries', manifest if isinstance(manifest, list) else None)
if entries is None:
    raise RuntimeError('Unexpected full_biography.json shape')

kid_id = 'music-kid-vinil-1993'
if not any(e.get('id') == kid_id for e in entries):
    idx = next(i for i, e in enumerate(entries) if e.get('id') == 'music-limonada-1992') + 1
    entries.insert(idx, {
        'id': kid_id,
        'era': 'cruzamentos-1992-2000',
        'date': '1993',
        'domain': 'music',
        'title': {
            'pt': 'Kid Vinil & Verminose — Café Piu Piu',
            'en': 'Kid Vinil & Verminose — Café Piu Piu'
        },
        'source': {
            'pt': {
                'path': 'pt/musica/index.html',
                'kind': 'phase',
                'selector': "[data-bio-key='music-kid-vinil-1993']",
                'parent_selector': '#palcos'
            },
            'en': {
                'path': 'en/music/index.html',
                'kind': 'phase',
                'selector': "[data-bio-key='music-kid-vinil-1993']",
                'parent_selector': '#stages'
            }
        }
    })

# Update the visible title of the existing 97FM Full Biography entry without changing its id.
for e in entries:
    if e.get('id') == 'music-coitado-1994':
        e.setdefault('title', {})['pt'] = 'Kid Vinil na 97FM Rock'
        e.setdefault('title', {})['en'] = 'Kid Vinil on 97FM Rock'
        break

manifest_path.write_text(json.dumps(manifest, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')

subprocess.run(['python', 'tools/sync_full_biography.py'], cwd=ROOT, check=True)
for entry_id in ['music-limonada-1992', 'music-kid-vinil-1993', 'music-coitado-1994']:
    subprocess.run(['python', 'tools/editorial_parity.py', '--accept', entry_id], cwd=ROOT, check=True)
subprocess.run(['python', 'tools/build_sitemap.py'], cwd=ROOT, check=True)
subprocess.run(['python', 'tools/sync_full_biography.py', '--check'], cwd=ROOT, check=True)
subprocess.run(['python', 'tools/editorial_parity.py', '--check'], cwd=ROOT, check=True)
